const $=s=>document.querySelector(s);const brl=c=>(Number(c||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let store=null,menu=null,cart=[],selectedSize=null,appliedCoupon=null;const selected=new Set();
async function api(path,opts={}){const token=localStorage.getItem('acaiCustomerToken');const r=await fetch('/api'+path,{headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`} : {}),...(opts.headers||{})},...opts});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Não foi possível concluir.');return data}
function priceForBuilder(){if(!selectedSize)return 0;return Number(selectedSize.price)+[...selected].reduce((sum,id)=>sum+Number(menu.options.find(o=>o.id===id)?.price||0),0)}
function renderOptions(category,target){const opts=menu.options.filter(o=>o.category===category);$(target).innerHTML=opts.map(o=>`<label class="option-pill ${selected.has(o.id)?'chosen':''}"><input type="checkbox" data-option="${o.id}" ${selected.has(o.id)?'checked':''}><span>${esc(o.name)}</span>${Number(o.price)>0?`<small>+ ${brl(o.price)}</small>`:'<small>Grátis</small>'}</label>`).join('')||'<p class="muted">Nenhuma opção disponível.</p>'}
function renderBuilder(){const product=menu.products[0];$('#sizes').innerHTML=product.sizes.map((s,i)=>`<label class="size-card ${selectedSize?.id===s.id?'chosen':''}"><input type="radio" name="size" data-size="${s.id}" ${selectedSize?.id===s.id?'checked':''}><span>${esc(s.name)}</span><strong>${brl(s.price)}</strong></label>`).join('');renderOptions('topping','#toppings');renderOptions('syrup','#syrups');renderOptions('extra','#extras');renderOptions('mousse','#mousses');$('#topping-counter').textContent=`${[...selected].filter(id=>menu.options.find(o=>o.id===id)?.category==='topping').length}/${store.maxFreeToppings}`;$('#unit-price').textContent=brl(priceForBuilder());}
function renderCart(){const count=cart.reduce((n,i)=>n+i.quantity,0),subtotal=cart.reduce((n,i)=>n+i.lineTotalCents,0),comboDiscount=store&&count>=store.comboMinItems?Math.floor(subtotal*store.comboDiscountPercent/100):0,couponDiscount=appliedCoupon?.discountCents||0;$('#cart-count').textContent=count;$('#cart-count-side').textContent=`${count} ${count===1?'item':'itens'}`;$('#cart-subtotal').textContent=brl(subtotal);$('#cart-final-total').textContent=brl(Math.max(0,subtotal-comboDiscount-couponDiscount));$('#combo-discount-row').classList.toggle('hidden',comboDiscount<=0);$('#combo-discount').textContent='- '+brl(comboDiscount);$('#coupon-discount-row').classList.toggle('hidden',couponDiscount<=0);$('#coupon-discount').textContent='- '+brl(couponDiscount);$('#cart-items').innerHTML=cart.length?cart.map((item,index)=>`<article class="cart-item"><div><strong>${item.quantity}× ${esc(item.size)}</strong><p>${item.options.length?item.options.map(o=>esc(o.name)).join(', '):'Sem adicionais'}</p><b>${brl(item.lineTotalCents)}</b></div><button class="remove-item" data-remove="${index}" aria-label="Remover item">×</button></article>`).join(''):'<p class="muted">Seu carrinho ainda está vazio.</p>';$('#mobile-cart-bar').classList.toggle('hidden',count===0);$('#mobile-cart-count').textContent=`${count} ${count===1?'item':'itens'}`;$('#mobile-cart-total').textContent=brl(Math.max(0,subtotal-comboDiscount-couponDiscount));saveCart();}
function updateZones(){const z=$('#zone-select');z.innerHTML='<option value="">Selecione seu bairro</option>'+menu.zones.map(x=>`<option value="${x.id}">${esc(x.name)} — ${brl(x.fee)}</option>`).join('');if(!menu.zones.length)z.innerHTML='<option value="">Nenhum bairro cadastrado</option>'}
async function load(){try{[store,menu]=await Promise.all([api('/store'),api('/menu')]);$('#store-status').textContent=store.openNow?'🟢 Aberto para pedidos imediatos · '+store.openingTime+' às '+store.closingTime:'🟣 No momento estamos fechados para pedidos imediatos. Você pode agendar.';paintStoreBanner();$('#delivery-estimate').textContent=`Previsão estimada: ${store.estimatedMinutesMin} a ${store.estimatedMinutesMax} minutos após a confirmação.`;$('#combo-promo-text').textContent=`Adicione ${store.comboMinItems} ou mais açaís ao carrinho e ganhe ${store.comboDiscountPercent}% de desconto automaticamente.`;if(!menu.products.length)throw new Error('O cardápio está indisponível.');selectedSize=menu.products[0].sizes[0]||null;$('#menu-status').classList.add('hidden');$('#builder').classList.remove('hidden');renderBuilder();updateZones();restoreSavedDetails();restoreCart();renderFavorites();}catch(e){$('#menu-status').textContent=e.message+' Confira a configuração do banco de dados e tente novamente.';$('#menu-status').classList.add('error-message')}await loadReviews()}
document.addEventListener('change',e=>{if(e.target.matches('[data-size]')){selectedSize=menu.products[0].sizes.find(s=>s.id===Number(e.target.dataset.size));renderBuilder()}if(e.target.matches('[data-option]')){const id=Number(e.target.dataset.option),opt=menu.options.find(o=>o.id===id);if(e.target.checked){if(opt.category==='syrup'){menu.options.filter(o=>o.category==='syrup').forEach(o=>selected.delete(o.id))}if(opt.category==='topping'&&[...selected].filter(i=>menu.options.find(o=>o.id===i)?.category==='topping').length>=store.maxFreeToppings){e.target.checked=false;$('#checkout-message').textContent=`Você pode escolher até ${store.maxFreeToppings} acompanhamentos grátis.`;$('#checkout-message').classList.add('error-message');return}selected.add(id)}else selected.delete(id);renderBuilder()}});
document.addEventListener('click',e=>{const remove=e.target.closest('[data-remove]');if(remove){cart.splice(Number(remove.dataset.remove),1);appliedCoupon=null;$('#coupon-message').textContent='';renderCart()}});
$('#add-cart').addEventListener('click',()=>{if(!selectedSize){$('#checkout-message').textContent='Escolha um tamanho antes de adicionar ao pedido.';$('#checkout-message').classList.add('error-message');return}const opts=[...selected].map(id=>menu.options.find(o=>o.id===id)).filter(Boolean);const unit=priceForBuilder(),quantity=Number($('#builder-quantity').value||1);cart.push({sizeId:selectedSize.id,size:selectedSize.name,quantity,optionIds:opts.map(o=>o.id),options:opts,unitPriceCents:unit,lineTotalCents:unit*quantity});appliedCoupon=null;$('#coupon-message').textContent='';selected.clear();renderBuilder();renderCart();$('#pedido').scrollIntoView({behavior:'smooth',block:'start'})});
$('#payment-method').addEventListener('change',e=>{const cash=e.target.value==='Dinheiro';$('#cash-change-fields').classList.toggle('hidden',!cash);$('#needs-change').required=cash;if(!cash){$('#needs-change').value='';$('#change-for').value='';$('#change-for-label').classList.add('hidden');$('#change-for').required=false;}});
$('#needs-change').addEventListener('change',e=>{const needs=e.target.value==='yes';$('#change-for-label').classList.toggle('hidden',!needs);$('#change-for').required=needs;if(!needs)$('#change-for').value='';});
$('#order-time').addEventListener('change',e=>{const scheduled=e.target.value==='scheduled';$('#schedule-label').classList.toggle('hidden',!scheduled);$('#scheduled-for').required=scheduled;if(scheduled){const min=new Date(Date.now()+Math.max(30,store?.minimumScheduleMinutes||30)*60000);min.setMinutes(Math.ceil(min.getMinutes()/5)*5,0,0);$('#scheduled-for').min=new Date(min.getTime()-min.getTimezoneOffset()*60000).toISOString().slice(0,16)}});
$('#apply-coupon').addEventListener('click',async()=>{const code=$('#coupon-code').value.trim().toUpperCase(),msg=$('#coupon-message'),subtotal=cart.reduce((sum,i)=>sum+i.lineTotalCents,0),itemCount=cart.reduce((sum,i)=>sum+i.quantity,0);msg.textContent='';if(!code){msg.textContent='Digite o código do cupom.';return}if(!cart.length){msg.textContent='Adicione itens ao carrinho antes de aplicar o cupom.';return}try{const c=await api(`/coupons/validate?code=${encodeURIComponent(code)}&subtotalCents=${subtotal}&itemCount=${itemCount}`);appliedCoupon=c;msg.textContent=`Cupom aplicado! Desconto de ${brl(c.discountCents)}.`;msg.classList.remove('error-message');renderCart()}catch(err){appliedCoupon=null;msg.textContent=err.message;msg.classList.add('error-message')}});
$('#coupon-code').addEventListener('input',()=>{appliedCoupon=null;$('#coupon-message').textContent='';renderCart()});
$('#checkout-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const msg=$('#checkout-message');msg.textContent='';if(!cart.length){msg.textContent='Adicione pelo menos um açaí ao pedido.';return}const fd=new FormData(form);const payload={customerName:fd.get('customerName'),phone:fd.get('phone'),address:fd.get('address'),zoneId:Number(fd.get('zoneId')),notes:fd.get('notes'),paymentMethod:fd.get('paymentMethod'),needsChange:fd.get('needsChange')||'no',changeFor:fd.get('changeFor')||'',scheduledFor:fd.get('orderTime')==='scheduled'?new Date(fd.get('scheduledFor')).toISOString():null,couponCode:appliedCoupon?.code||'',items:cart.map(i=>({sizeId:i.sizeId,quantity:i.quantity,optionIds:i.optionIds}))};const button=$('#submit-order');button.disabled=true;button.textContent='Registrando pedido…';try{const order=await api('/orders',{method:'POST',body:JSON.stringify(payload)});const lines=order.items.map(i=>`• ${i.quantity}x ${i.product} (${i.size})\n  ${i.options.map(o=>o.name).join(', ')||'Sem adicionais'} — ${brl(i.lineTotalCents)}`).join('\n');const scheduled=order.scheduledFor?`\nAgendamento: ${new Date(order.scheduledFor).toLocaleString('pt-BR')}`:'\nEntrega: assim que possível';const text=`Olá! Quero confirmar o pedido ${order.orderCode} no Açaí da Roça.\n\n${lines}\n\nSubtotal: ${brl(order.subtotalCents)}${order.comboDiscountCents?`\nDesconto combo: -${brl(order.comboDiscountCents)}`:''}${order.discountCents?`\nCupom ${order.couponCode}: -${brl(order.discountCents)}`:''}\nEntrega (${order.neighborhood}): ${brl(order.deliveryFeeCents)}\nTOTAL: ${brl(order.totalCents)}\nPrevisão estimada: ${order.estimatedMinutesMin} a ${order.estimatedMinutesMax} minutos\n\nNome: ${order.customerName}\nTelefone: ${order.phone}\nEndereço: ${order.address}
Forma de pagamento: ${order.paymentMethod}${order.changeFor?`\nTroco para: R$ ${order.changeFor}`:''}${scheduled}${order.notes?'\nObservações: '+order.notes:''}\n\nO pedido foi registrado pelo site.`;msg.textContent=`Pedido ${order.orderCode} registrado! Guarde esse código para acompanhar, editar ou cancelar seu pedido na seção “Acompanhe seu pedido”. Abrindo o WhatsApp…`;$('#tracking-form [name=code]').value=order.orderCode;$('#tracking-form [name=phone]').value=order.phone;if($('#save-customer-details').checked){localStorage.setItem('acaiCustomerDetails',JSON.stringify({customerName:order.customerName,phone:order.phone,address:order.address,zoneId:fd.get('zoneId')}));}else{localStorage.removeItem('acaiCustomerDetails');}if(localStorage.getItem('acaiCustomerToken'))loadCustomerAccount();cart=[];appliedCoupon=null;$('#coupon-code').value='';$('#coupon-message').textContent='';renderCart();window.open(`https://wa.me/${String(order.whatsappNumber||'').replace(/\D/g,'')}?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');form.reset();$('#schedule-label').classList.add('hidden')}catch(err){msg.textContent=err.message}finally{button.disabled=false;button.textContent='Confirmar pedido no WhatsApp'}});
async function loadReviews(){try{const reviews=await api('/reviews');$('#reviews-list').innerHTML=reviews.length?reviews.map(r=>`<article class="review-card"><div class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><strong>${esc(r.name)}</strong><p>${esc(r.comment)}</p></article>`).join(''):'<p class="muted">Ainda não há avaliações publicadas. Seja a primeira pessoa a avaliar!</p>'}catch{$('#reviews-list').innerHTML='<p class="muted">Avaliações indisponíveis no momento.</p>'}}
$('#review-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const msg=$('#review-message');try{const fd=new FormData(form);const data=await api('/reviews',{method:'POST',body:JSON.stringify({name:fd.get('name'),rating:Number(fd.get('rating')),comment:fd.get('comment')})});msg.textContent=data.message;form.reset()}catch(err){msg.textContent=err.message}});
// Conta do cliente: celular + senha. Pedidos anteriores não são associados automaticamente.
function setAccountView(signedIn){$('#account-signed-out').classList.toggle('hidden',signedIn);$('#account-signed-in').classList.toggle('hidden',!signedIn)}
function customerMessage(id,text,error=false){const el=$(id);if(el){el.textContent=text;el.classList.toggle('error-message',error)}}
var mustChangeShown=false;
async function loadCustomerAccount(){try{const data=await api('/customers/me');setAccountView(true);applyAuthUI(data.customer,data.loyaltyBalance);$('#customer-greeting').textContent=`Olá, ${data.customer.name}!` ;$('#customer-phone-display').textContent=data.customer.phone;$('#customer-profile-form [name=name]').value=data.customer.name;$('#customer-profile-form [name=phone]').value=data.customer.phone;$('#customer-profile-form').dataset.phone=data.customer.phone;$('#checkout-form [name=phone]').value=data.customer.phone;$('#checkout-form [name=customerName]').value=data.customer.name;if(data.mustChangePassword&&!mustChangeShown){mustChangeShown=true;promptPasswordChange()}}catch{localStorage.removeItem('acaiCustomerToken');setAccountView(false);applyAuthUI(null);return}
loadCustomerOrders();loadFavorites()}
async function loadCustomerOrders(){const list=$('#customer-orders-list');try{const result=await api('/customers/me/orders');list.innerHTML=result.orders.length?result.orders.map(o=>`<article class="customer-order-card"><div class="tracking-top"><div><small>${new Date(o.created_at).toLocaleString('pt-BR')}</small><h4>${esc(o.order_code)}</h4></div><span class="status status-${esc(o.status)}">${statusNames[o.status]||esc(o.status)}</span></div><p>${(o.items||[]).map(i=>`${i.quantity}× ${esc(i.size)}${i.options?.length?' — '+i.options.map(x=>esc(x.name)).join(', '):''}`).join('<br>')}</p><strong>${brl(o.total_cents)}</strong><button type="button" class="button button-outline customer-track-order" data-order-code="${esc(o.order_code)}" data-order-phone="${esc(o.customer_phone)}">Acompanhar pedido</button></article>`).join(''):'<p class="muted">Você ainda não tem pedidos associados à sua conta. Faça um pedido enquanto estiver conectado e ele aparecerá aqui.</p>';customerMessage('#customer-orders-message','')}catch(err){if(!list.querySelector('.customer-order-card'))list.innerHTML='<p class="muted">Não foi possível carregar seus pedidos agora.</p>'}}
function promptPasswordChange(){openSettings();const f=$('#customer-password-form');const d=f.closest('details');if(d)d.open=true;customerMessage('#customer-password-message','Você entrou com uma senha temporária. Crie uma nova senha para proteger sua conta.',true)}
$('#customer-login-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const fd=new FormData(form);customerMessage('#customer-login-message','Entrando…');try{const data=await api('/customers/login',{method:'POST',body:JSON.stringify({phone:fd.get('phone'),password:fd.get('password')})});localStorage.setItem('acaiCustomerToken',data.token);customerMessage('#customer-login-message','');form.reset();await loadCustomerAccount();$('#minha-conta').scrollIntoView({behavior:'smooth'});}catch(err){customerMessage('#customer-login-message',err.message,true)}});
$('#customer-register-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;const fd=new FormData(form);customerMessage('#customer-register-message','Criando sua conta…');try{const data=await api('/customers/register',{method:'POST',body:JSON.stringify({name:fd.get('name'),phone:fd.get('phone'),password:fd.get('password')})});localStorage.setItem('acaiCustomerToken',data.token);form.reset();customerMessage('#customer-register-message','');await loadCustomerAccount();$('#minha-conta').scrollIntoView({behavior:'smooth'});}catch(err){customerMessage('#customer-register-message',err.message,true)}});
function doLogout(){localStorage.removeItem('acaiCustomerToken');localStorage.removeItem('acaiOrderStatuses');setAccountView(false);applyAuthUI(null);customerMessage('#customer-login-message','Você saiu da sua conta.');}
$('#customer-logout').addEventListener('click',doLogout);
$('#customer-profile-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),form=e.currentTarget;customerMessage('#customer-profile-message','Salvando…');try{const body={name:fd.get('name'),phone:fd.get('phone')};const changedPhone=String(fd.get('phone')||'').replace(/\D/g,'')!==String(form.dataset.phone||'').replace(/\D/g,'');if(changedPhone)body.currentPassword=fd.get('currentPassword')||'';await api('/customers/me',{method:'PATCH',body:JSON.stringify(body)});form.querySelector('[name=currentPassword]').value='';$('#profile-password-label').classList.add('hidden');customerMessage('#customer-profile-message','Dados atualizados.');await loadCustomerAccount()}catch(err){customerMessage('#customer-profile-message',err.message,true)}});
$('#customer-password-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form);try{const data=await api('/customers/me/password',{method:'POST',body:JSON.stringify({currentPassword:fd.get('currentPassword'),newPassword:fd.get('newPassword')})});customerMessage('#customer-password-message',data.message);form.reset()}catch(err){customerMessage('#customer-password-message',err.message,true)}});
document.addEventListener('click',e=>{const b=e.target.closest('.customer-track-order');if(!b)return;$('#tracking-form [name=code]').value=b.dataset.orderCode;$('#tracking-form [name=phone]').value=b.dataset.orderPhone;$('#tracking-form').requestSubmit();$('#acompanhar').scrollIntoView({behavior:'smooth'});});
if(localStorage.getItem('acaiCustomerToken'))loadCustomerAccount();else{setAccountView(false);applyAuthUI(null)}
$('#year').textContent=new Date().getFullYear();load();

const statusNames={new:'Recebido',preparing:'Em preparo',out_for_delivery:'Saiu para entrega',delivered:'Entregue',cancelled:'Cancelado'};
let trackedOrder=null;
function whatsapp(text,number){const n=String(number||'').replace(/\D/g,'');if(n.length<10){throw new Error('O WhatsApp da loja não está configurado corretamente. Entre em contato com a loja por outro canal.')}window.open(`https://wa.me/${n}?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer')}
function orderSummary(o,heading){const lines=(o.items||[]).map(i=>`• ${i.quantity}x ${i.product} (${i.size}) — ${brl(i.lineTotalCents)}\n  ${(i.options||[]).map(x=>x.name).join(', ')||'Sem adicionais'}`).join('\n');return `${heading} ${o.orderCode} — Açaí da Roça\n\n${lines}\n\nSubtotal: ${brl(o.subtotalCents)}${o.comboDiscountCents?`\nDesconto combo: -${brl(o.comboDiscountCents)}`:''}${o.discountCents?`\nCupom ${o.couponCode}: -${brl(o.discountCents)}`:''}\nEntrega (${o.neighborhood}): ${brl(o.deliveryFeeCents)}\nTOTAL: ${brl(o.totalCents)}\n\nNome: ${o.customerName}\nTelefone: ${o.phone}\nEndereço: ${o.address}\nPagamento: ${o.paymentMethod||'A combinar'}${o.changeFor?`\nTroco para: R$ ${o.changeFor}`:''}\nObservações: ${o.notes||'Nenhuma'}\n\n${o.scheduledFor?'Agendamento: '+new Date(o.scheduledFor).toLocaleString('pt-BR'):'Entrega assim que possível'}\nPrevisão estimada: ${o.estimatedMinutesMin||35} a ${o.estimatedMinutesMax||55} minutos`}
function renderTracking(o){trackedOrder=o;trackDirty=false;const result=$('#tracking-result');const rawSizes=(menu?.products?.flatMap(p=>p.sizes)||[]).slice().sort((a,b)=>Number(a.sort_order??0)-Number(b.sort_order??0)||Number(a.id)-Number(b.id));const seenSizeNames=new Set();const allSizes=rawSizes.filter(sz=>{const key=String(sz.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('pt-BR');if(!key||seenSizeNames.has(key))return false;seenSizeNames.add(key);return true;});const items=o.items.map((i,index)=>{const sizeOptions=allSizes.map(sz=>`<option value="${sz.id}" ${Number(sz.id)===Number(i.sizeId)?'selected':''}>${esc(sz.name)} — ${brl(sz.price)}</option>`).join('');const optionGroups=[['topping','Acompanhamentos'],['syrup','Calda'],['extra','Adicionais'],['mousse','Mousses']].map(([category,label])=>{const opts=(menu?.options||[]).filter(x=>x.category===category);if(!opts.length)return '';return `<fieldset class="edit-option-group"><legend>${label}</legend><div class="edit-option-list">${opts.map(opt=>`<label><input type="checkbox" data-edit-option="${opt.id}" data-edit-category="${category}" data-edit-index="${index}" ${i.options.some(x=>Number(x.id)===Number(opt.id))?'checked':''}> ${esc(opt.name)}${Number(opt.price)>0?` (+ ${brl(opt.price)})`:''}</label>`).join('')}</div></fieldset>`}).join('');const currentOptions=i.options.map(x=>esc(x.name)).join(', ')||'Sem acompanhamentos';return `<div class="tracking-item tracking-item-edit"><div class="tracking-item-heading"><strong>Item ${index+1}</strong>${o.canEdit?`<label class="tracking-qty">Quantidade<input type="number" min="0" max="20" value="${i.quantity}" data-track-qty="${index}"></label>`:`<span>Quantidade: ${i.quantity}</span>`}</div>${o.canEdit?`<label class="edit-size-label">Tamanho do açaí<select data-edit-size="${index}">${sizeOptions}</select></label>${optionGroups}<p class="muted">Quantidade 0 remove este item do pedido.</p>`:`<p><strong>${esc(i.size)}</strong></p><p>${currentOptions}</p>`}</div>`}).join('');result.innerHTML=`<div class="tracking-card"><div class="tracking-top"><div><small>Pedido</small><h3>${esc(o.orderCode)}</h3></div><span class="status status-${o.status}">${statusNames[o.status]||o.status}</span></div><p><strong>Cliente:</strong> ${esc(o.customerName)}</p><p><strong>Entrega:</strong> ${esc(o.address)} — ${esc(o.neighborhood)}</p><p><strong>Pagamento:</strong> ${esc(o.paymentMethod||'A combinar')}${o.changeFor?` — Troco para R$ ${esc(o.changeFor)}`:''}</p><p class="estimate-note"><strong>Previsão estimada:</strong> ${o.estimatedMinutesMin||35} a ${o.estimatedMinutesMax||55} minutos após confirmação.</p><p class="loyalty-note">💜 Programa de fidelidade: ${o.loyaltyBalance||0} ponto(s) acumulado(s) neste telefone.${o.earnedPoints?` Este pedido rendeu ${o.earnedPoints} ponto(s)!`:''} A cada R$ 1 em pedidos entregues, você ganha 1 ponto.</p><div class="tracking-progress"><span class="${o.status!=='cancelled'?'done':''}">Recebido</span><span class="${['preparing','out_for_delivery','delivered'].includes(o.status)?'done':''}">Em preparo</span><span class="${['out_for_delivery','delivered'].includes(o.status)?'done':''}">Saiu para entrega</span><span class="${o.status==='delivered'?'done':''}">Entregue</span></div><h4>Itens do pedido</h4>${o.canEdit?`<p class="muted">Altere tamanho, calda, acompanhamentos, adicionais, mousses e quantidade. Quantidade 0 remove o item.</p>`:''}<div class="tracking-items">${items}</div><div class="tracking-total"><span>Total${o.comboDiscountCents?` · combo (-${brl(o.comboDiscountCents)})`:''}${o.discountCents?` · cupom ${esc(o.couponCode)} (-${brl(o.discountCents)})`:''}</span><strong>${brl(o.totalCents)}</strong></div><button class="button button-outline" id="repeat-tracked-order" type="button">Repetir este pedido</button><p id="repeat-order-message" class="form-message" role="status"></p>${o.canEdit?`<form id="customer-edit-form" class="customer-edit"><h4>Editar dados da entrega</h4><label>Nome<input name="customerName" required value="${esc(o.customerName)}"></label><label>Endereço<input name="address" required value="${esc(o.address)}"></label><label>Bairro<select name="zoneId"><option value="">Manter bairro atual (${esc(o.neighborhood)})</option>${(menu?.zones||[]).map(z=>`<option value="${z.id}" ${z.name===o.neighborhood?'selected':''}>${esc(z.name)} — ${brl(z.fee)}</option>`).join('')}</select></label><label>Observações<textarea name="notes" rows="2">${esc(o.notes||'')}</textarea></label><button class="button button-primary" type="submit">Salvar alterações</button><p class="form-message error-message" id="edit-order-message" role="alert"></p></form><button class="button button-danger" id="cancel-customer-order" type="button">Cancelar pedido</button>`:''}<p class="form-message error-message" id="tracking-action-message" role="alert"></p></div>`;result.classList.remove('hidden');}
$('#tracking-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),msg=$('#tracking-message');msg.textContent='Consultando pedido…';$('#tracking-result').classList.add('hidden');try{const o=await api(`/orders/track?code=${encodeURIComponent(fd.get('code'))}&phone=${encodeURIComponent(fd.get('phone'))}`);o.lookupPhone=fd.get('phone');renderTracking(o);msg.textContent='';startLiveTracking();}catch(err){msg.textContent=err.message;}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-edit-option]'))return;const checkbox=e.target;if(checkbox.dataset.editCategory!=='topping'||!checkbox.checked)return;const index=checkbox.dataset.editIndex;const checked=document.querySelectorAll(`[data-edit-index="${index}"][data-edit-category="topping"]:checked`).length;const limit=Number(store?.maxFreeToppings||5);if(checked>limit){checkbox.checked=false;const msg=$('#edit-order-message')||$('#tracking-action-message');if(msg){msg.textContent=`Você pode escolher no máximo ${limit} acompanhamentos por açaí.`;msg.classList.add('error-message');}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='customer-edit-form')return;e.preventDefault();if(!trackedOrder)return;const fd=new FormData(e.target),msg=$('#edit-order-message');msg.textContent='Salvando alterações…';const quantities=[...document.querySelectorAll('[data-track-qty]')].map(el=>({index:Number(el.dataset.trackQty),quantity:Number(el.value),sizeId:Number(document.querySelector(`[data-edit-size="${el.dataset.trackQty}"]`)?.value),optionIds:[...document.querySelectorAll(`[data-edit-index="${el.dataset.trackQty}"][data-edit-option]:checked`)].map(x=>Number(x.dataset.editOption))})).filter(x=>x.quantity>0);if(!quantities.length){msg.textContent='O pedido precisa ter pelo menos um item.';return}try{const updated=await api(`/orders/${trackedOrder.orderCode}/customer`,{method:'PATCH',body:JSON.stringify({phone:trackedOrder.lookupPhone,customerName:fd.get('customerName'),address:fd.get('address'),zoneId:fd.get('zoneId')?Number(fd.get('zoneId')):undefined,notes:fd.get('notes'),items:quantities})});updated.lookupPhone=trackedOrder.lookupPhone;renderTracking(updated);whatsapp(orderSummary(updated,'Olá! Quero confirmar a EDIÇÃO do pedido'),' '+updated.whatsappNumber);$('#tracking-action-message').textContent='Alteração registrada! Envie a mensagem no WhatsApp para avisar a loja.';}catch(err){msg.textContent=err.message;}});
document.addEventListener('click',async e=>{if(e.target.id==='repeat-tracked-order'&&trackedOrder){const message=$('#repeat-order-message');const repeated=[];for(const item of trackedOrder.items||[]){const size=menu?.products?.flatMap(p=>p.sizes||[]).find(s=>Number(s.id)===Number(item.sizeId));if(!size)continue;const options=(item.options||[]).map(old=>menu.options.find(o=>Number(o.id)===Number(old.id)&&o.active!==false)).filter(Boolean);const unit=Number(size.price)+options.reduce((sum,o)=>sum+Number(o.price||0),0);repeated.push({sizeId:size.id,size:size.name,quantity:item.quantity,optionIds:options.map(o=>o.id),options,unitPriceCents:unit,lineTotalCents:unit*item.quantity})}if(!repeated.length){message.textContent='Os itens deste pedido não estão mais disponíveis no cardápio.';return}cart.push(...repeated);appliedCoupon=null;$('#coupon-code').value='';$('#coupon-message').textContent='';renderCart();message.textContent=repeated.length<(trackedOrder.items||[]).length?'Alguns itens não estão mais disponíveis e não foram adicionados.':'Itens adicionados novamente ao carrinho!';$('#pedido').scrollIntoView({behavior:'smooth',block:'start'});return;}if(e.target.id!=='cancel-customer-order'||!trackedOrder)return;if(!confirm('Tem certeza de que deseja cancelar este pedido?'))return;const msg=$('#tracking-action-message');msg.textContent='Cancelando pedido…';try{const r=await api(`/orders/${trackedOrder.orderCode}/cancel`,{method:'POST',body:JSON.stringify({phone:trackedOrder.lookupPhone})});trackedOrder.status='cancelled';trackedOrder.canEdit=false;trackedOrder.canCancel=false;renderTracking(trackedOrder);whatsapp(`Olá! Solicito o CANCELAMENTO do pedido ${r.order_code} no Açaí da Roça. O pedido foi cancelado pelo site.`,r.whatsappNumber);$('#tracking-action-message').textContent='Pedido cancelado no site. Envie a mensagem no WhatsApp para avisar a loja.';}catch(err){msg.textContent=err.message;}});

// Cadastro rápido opcional: dados ficam somente neste aparelho, sem criar conta ou enviar senha.
function restoreSavedDetails(){try{const saved=JSON.parse(localStorage.getItem('acaiCustomerDetails')||'null');if(saved){for(const [key,value] of Object.entries({customerName:saved.customerName,phone:saved.phone,address:saved.address})){const field=document.querySelector(`#checkout-form [name=\"${key}\"]`);if(field&&value)field.value=value;}if(saved.zoneId)$('#zone-select').value=saved.zoneId;$('#save-customer-details').checked=true;}}catch{}}
let deferredInstallPrompt=null;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;$('#install-app').classList.remove('hidden')});$('#install-app').addEventListener('click',async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;$('#install-app').classList.add('hidden')}else{alert('No iPhone: toque em Compartilhar e depois em “Adicionar à Tela de Início”. No Android, use o menu do navegador e escolha “Instalar app” ou “Adicionar à tela inicial”.')}});if(/iphone|ipad|ipod/i.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches){$('#install-app').classList.remove('hidden');$('#install-app').textContent='Como instalar'}if(window.matchMedia('(display-mode: standalone)').matches)$('#install-app').classList.add('hidden');window.addEventListener('appinstalled',()=>$('#install-app').classList.add('hidden'));if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js').catch(err=>console.warn('PWA indisponível:',err)));

// ===== Menu lateral, estado de login no topo e configurações =====
const THEME_COLORS={light:'#321047',dark:'#1a0a24'};
const darkQuery=window.matchMedia('(prefers-color-scheme: dark)');
function applyTheme(pref,persist){if(!['light','dark','auto'].includes(pref))pref='auto';const dark=pref==='dark'||(pref==='auto'&&darkQuery.matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.themePref=pref;const meta=$('#meta-theme-color');if(meta)meta.content=dark?THEME_COLORS.dark:THEME_COLORS.light;if(persist){try{localStorage.setItem('acaiTheme',pref)}catch{}}}
function currentThemePref(){try{return localStorage.getItem('acaiTheme')||'auto'}catch{return 'auto'}}
(darkQuery.addEventListener?darkQuery.addEventListener.bind(darkQuery,'change'):darkQuery.addListener.bind(darkQuery))(()=>{if(currentThemePref()==='auto')applyTheme('auto',false)});
function applyFontScale(v,persist){if(!['normal','large','xlarge'].includes(v))v='normal';if(v==='normal')delete document.documentElement.dataset.fontScale;else document.documentElement.dataset.fontScale=v;if(persist){try{localStorage.setItem('acaiFontScale',v==='normal'?'':v)}catch{}}}
function currentFontScale(){try{return localStorage.getItem('acaiFontScale')||'normal'}catch{return 'normal'}}

// Menu lateral
const sideMenu=$('#side-menu'),menuToggle=$('#menu-toggle'),menuOverlay=$('#menu-overlay');
function isMenuOpen(){return sideMenu.classList.contains('open')}
function openMenu(){sideMenu.classList.add('open');sideMenu.setAttribute('aria-hidden','false');menuOverlay.classList.remove('hidden');document.body.classList.add('menu-open');menuToggle.setAttribute('aria-expanded','true');menuToggle.setAttribute('aria-label','Fechar menu');menuToggle.classList.add('is-open')}
function closeMenu(){sideMenu.classList.remove('open');sideMenu.setAttribute('aria-hidden','true');menuOverlay.classList.add('hidden');if(!isSettingsOpen())document.body.classList.remove('menu-open');menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Abrir menu');menuToggle.classList.remove('is-open')}
menuToggle.addEventListener('click',()=>isMenuOpen()?closeMenu():openMenu());
menuOverlay.addEventListener('click',closeMenu);
document.addEventListener('click',e=>{if(isMenuOpen()&&!e.target.closest('#side-menu')&&!e.target.closest('#menu-toggle'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(isSettingsOpen())closeSettings();else if(isMenuOpen()){closeMenu();menuToggle.focus()}});
function goTo(selector,focusSel){setTimeout(()=>{const el=$(selector);if(el){el.scrollIntoView({behavior:'smooth',block:'start'});if(focusSel){const f=$(focusSel);if(f)setTimeout(()=>f.focus({preventScroll:true}),450)}}},60)}
sideMenu.addEventListener('click',e=>{const b=e.target.closest('[data-menu-action]');if(!b)return;const a=b.dataset.menuAction;closeMenu();if(a==='account')goTo('#minha-conta');else if(a==='orders')goTo('#meus-pedidos');else if(a==='favorites')goTo('#meus-favoritos');else if(a==='settings')openSettings();else if(a==='logout')doLogout();else if(a==='login')goTo('#customer-login-form','#customer-login-form [name=phone]');else if(a==='register')goTo('#customer-register-form','#customer-register-form [name=name]');else if(a==='track')goTo('#acompanhar')});

// Estado de login no cabeçalho e no menu
function setPoints(n){const has=typeof n==='number';const txt=has?`💜 ${n} ${n===1?'ponto':'pontos'} no Clube da Roça`:'';$('#menu-points').textContent=txt;$('#menu-points').classList.toggle('hidden',!has);$('#customer-points').textContent=has?`${txt} · cada R$ 1 em pedidos entregues vale 1 ponto`:'';$('#customer-points').classList.toggle('hidden',!has)}
function applyAuthUI(customer,points){const signedIn=!!customer;document.body.dataset.auth=signedIn?'in':'out';const first=signedIn?String(customer.name||'').trim().split(/\s+/)[0]:'';$('#header-greeting').textContent=signedIn?`Olá, ${first}! 👋`:'';$('#header-greeting').classList.toggle('hidden',!signedIn);$('#header-login').classList.toggle('hidden',signedIn);$('#header-register').classList.toggle('hidden',signedIn);$('#menu-signed-in').classList.toggle('hidden',!signedIn);$('#menu-signed-out').classList.toggle('hidden',signedIn);$('#side-menu-hello').textContent=signedIn?`Olá, ${first}! 👋`:'Olá! 👋';$('#side-menu-sub').textContent=signedIn?customer.phone:'Entre para ver seus pedidos';setPoints(signedIn&&typeof points==='number'?points:null);if(signedIn){restartOrderWatcher();startAccountLive()}else{stopOrderWatcher();stopAccountLive();favorites=[];favoritesLoaded=false}}

// Configurações
const settingsModal=$('#settings-modal');let settingsReturnFocus=null;
function isSettingsOpen(){return !settingsModal.classList.contains('hidden')}
function openSettings(){settingsReturnFocus=document.activeElement;syncSettingsUI();settingsModal.classList.remove('hidden');document.body.classList.add('menu-open');setTimeout(()=>$('.settings-close').focus(),30)}
function closeSettings(){settingsModal.classList.add('hidden');document.body.classList.remove('menu-open');if(settingsReturnFocus&&settingsReturnFocus.focus)settingsReturnFocus.focus()}
settingsModal.addEventListener('click',e=>{if(e.target.closest('[data-settings-close]'))closeSettings()});
function syncSettingsUI(){const t=currentThemePref();document.querySelectorAll('[name=theme]').forEach(r=>r.checked=r.value===t);const f=currentFontScale();document.querySelectorAll('[name=fontScale]').forEach(r=>r.checked=r.value===f);fillPrefsForm();syncNotifyUI();syncPwaUI()}
document.addEventListener('change',e=>{if(e.target.name==='theme')applyTheme(e.target.value,true);if(e.target.name==='fontScale')applyFontScale(e.target.value,true)});
$('#customer-profile-form [name=phone]').addEventListener('input',e=>{const changed=e.target.value.replace(/\D/g,'')!==String($('#customer-profile-form').dataset.phone||'').replace(/\D/g,'');$('#profile-password-label').classList.toggle('hidden',!changed)});

// Preferências de entrega (salvas neste aparelho)
function populatePrefsZones(){const z=$('#prefs-zone');if(!z||!menu?.zones)return;z.innerHTML='<option value="">Selecione o bairro</option>'+menu.zones.map(x=>`<option value="${x.id}">${esc(x.name)} — ${brl(x.fee)}</option>`).join('')}
function fillPrefsForm(){let saved=null;try{saved=JSON.parse(localStorage.getItem('acaiCustomerDetails')||'null')}catch{}populatePrefsZones();const f=$('#delivery-prefs-form');f.customerName.value=saved?.customerName||f.customerName.value||'';f.phone.value=saved?.phone||f.phone.value||'';f.address.value=saved?.address||f.address.value||'';if(saved?.zoneId)f.zoneId.value=saved.zoneId}
$('#delivery-prefs-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,msg=$('#prefs-message');const data={customerName:f.customerName.value.trim(),phone:f.phone.value.trim(),address:f.address.value.trim(),zoneId:f.zoneId.value};if(!data.customerName&&!data.phone&&!data.address&&!data.zoneId){msg.textContent='Preencha pelo menos um campo para salvar.';msg.classList.add('error-message');return}try{localStorage.setItem('acaiCustomerDetails',JSON.stringify(data))}catch{msg.textContent='Não foi possível salvar neste navegador.';msg.classList.add('error-message');return}const c=$('#checkout-form');if(data.customerName)c.customerName.value=data.customerName;if(data.phone)c.phone.value=data.phone;if(data.address)c.address.value=data.address;if(data.zoneId)$('#zone-select').value=data.zoneId;$('#save-customer-details').checked=true;msg.classList.remove('error-message');msg.textContent='Preferências salvas! Elas já aparecem no seu próximo pedido.'});
$('#prefs-clear').addEventListener('click',()=>{try{localStorage.removeItem('acaiCustomerDetails')}catch{}const f=$('#delivery-prefs-form');f.reset();$('#save-customer-details').checked=false;const msg=$('#prefs-message');msg.classList.remove('error-message');msg.textContent='Dados de entrega apagados deste aparelho.'});

// Notificações de pedidos (avisos enquanto o site estiver aberto)
var notifySupported="Notification" in window;var orderWatchTimer=null;
function notifyEnabled(){return localStorage.getItem('acaiNotify')==='1'&&notifySupported&&Notification.permission==='granted'}
function syncNotifyUI(){const t=$('#notify-toggle'),help=$('#notify-help');if(!notifySupported){t.checked=false;t.disabled=true;help.textContent='Este navegador não oferece suporte a notificações.';return}if(Notification.permission==='denied'){t.checked=false;t.disabled=true;help.textContent='As notificações estão bloqueadas no navegador. Libere nas configurações do site para ativar.';return}t.disabled=false;t.checked=notifyEnabled()}
$('#notify-toggle').addEventListener('change',async e=>{const msg=$('#notify-message');msg.textContent='';msg.classList.remove('error-message');if(e.target.checked){const perm=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(perm==='granted'){localStorage.setItem('acaiNotify','1');msg.textContent='Avisos de pedidos ativados.';restartOrderWatcher()}else{e.target.checked=false;localStorage.removeItem('acaiNotify');msg.textContent='Permissão não concedida. Ative as notificações no navegador para receber avisos.';msg.classList.add('error-message')}}else{localStorage.removeItem('acaiNotify');msg.textContent='Avisos de pedidos desativados.';stopOrderWatcher()}syncNotifyUI()});
async function showOrderNotice(title,body){try{const reg=await navigator.serviceWorker?.getRegistration();if(reg?.showNotification){await reg.showNotification(title,{body,icon:'/images/icon-192.png',badge:'/images/icon-192.png',tag:'acai-pedido'});return}}catch{}try{new Notification(title,{body,icon:'/images/icon-192.png'})}catch{}}
async function checkOrderStatuses(){if(!notifyEnabled()||!localStorage.getItem('acaiCustomerToken'))return;try{const r=await api('/customers/me/orders');let prev={};try{prev=JSON.parse(localStorage.getItem('acaiOrderStatuses')||'null')||{}}catch{}const first=!Object.keys(prev).length&&!localStorage.getItem('acaiOrderStatuses');const next={};for(const o of r.orders){next[o.order_code]=o.status;if(!first&&prev[o.order_code]&&prev[o.order_code]!==o.status){showOrderNotice(`Pedido ${o.order_code}`,`Status atualizado: ${statusNames[o.status]||o.status}`)}}localStorage.setItem('acaiOrderStatuses',JSON.stringify(next))}catch{}}
function stopOrderWatcher(){if(orderWatchTimer){clearInterval(orderWatchTimer);orderWatchTimer=null}}
function restartOrderWatcher(){stopOrderWatcher();if(!notifyEnabled())return;checkOrderStatuses();orderWatchTimer=setInterval(checkOrderStatuses,60000)}

// Aplicativo (PWA)
function syncPwaUI(){const standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone;$('#pwa-status').textContent=standalone?'O aplicativo já está instalado e em uso neste aparelho. ✅':'Você pode instalar o Açaí da Roça no celular e abrir como um aplicativo.';$('#settings-install').classList.toggle('hidden',!!standalone);$('#app-version').textContent='Açaí da Roça · versão da interface 20261101'}
$('#settings-install').addEventListener('click',()=>$('#install-app').click());

applyTheme(currentThemePref(),false);applyFontScale(currentFontScale(),false);

// ===== Carrinho salvo no aparelho =====
function buildCartItem(sizeId,optionIds,qty){const size=menu?.products?.flatMap(p=>p.sizes||[]).find(x=>Number(x.id)===Number(sizeId));if(!size)return null;const options=(optionIds||[]).map(id=>menu.options.find(o=>Number(o.id)===Number(id))).filter(Boolean);const unit=Number(size.price)+options.reduce((n,o)=>n+Number(o.price||0),0);return{sizeId:size.id,size:size.name,quantity:qty,optionIds:options.map(o=>o.id),options,unitPriceCents:unit,lineTotalCents:unit*qty}}
function saveCart(){try{if(!menu)return;if(!cart.length){localStorage.removeItem('acaiCart');return}localStorage.setItem('acaiCart',JSON.stringify({t:Date.now(),items:cart.map(i=>({s:i.sizeId,q:i.quantity,o:i.optionIds}))}))}catch{}}
function restoreCart(){try{const saved=JSON.parse(localStorage.getItem('acaiCart')||'null');if(!saved||!Array.isArray(saved.items)||Date.now()-Number(saved.t||0)>7*86400000||cart.length)return;const restored=saved.items.map(i=>buildCartItem(i.s,i.o,Math.min(20,Math.max(1,Number(i.q)||1)))).filter(Boolean);if(!restored.length){localStorage.removeItem('acaiCart');return}cart.push(...restored);renderCart();const m=$('#checkout-message');m.textContent=restored.length<saved.items.length?'Recuperamos seu pedido anterior. Alguns itens saíram do cardápio e foram removidos.':'Recuperamos os itens do seu pedido anterior. 💜';m.classList.remove('error-message')}catch{}}

// ===== Favoritos =====
var favorites=[],favoritesLoaded=false;
async function loadFavorites(){try{const r=await api('/customers/me/favorites');favorites=r.favorites||[];favoritesLoaded=true;renderFavorites()}catch{$('#favorites-list').innerHTML='<p class="muted">Não foi possível carregar seus favoritos agora.</p>'}}
function renderFavorites(){const list=$('#favorites-list');if(!list||!favoritesLoaded)return;if(!favorites.length){list.innerHTML='<p class="muted">Você ainda não tem favoritos. Monte um açaí no cardápio e toque em “Salvar este açaí como favorito”.</p>';return}if(!menu){list.innerHTML='<p class="muted">Carregando cardápio…</p>';return}list.innerHTML=favorites.map(f=>{const item=buildCartItem(f.sizeId,f.optionIds,1);const missing=!item||item.optionIds.length<(f.optionIds||[]).length;return `<article class="favorite-card"><div><strong>${esc(f.name)}</strong><p class="muted">${item?esc(item.size)+(item.options.length?' — '+item.options.map(o=>esc(o.name)).join(', '):' — sem adicionais'):'Este tamanho não está mais disponível.'}</p>${missing&&item?'<small class="error-message">Algumas opções não estão mais disponíveis.</small>':''}${item?`<b>${brl(item.unitPriceCents)}</b>`:''}</div><div class="favorite-actions"><button type="button" class="button button-green button-small" data-fav-add="${f.id}" ${item?'':'disabled'}>Adicionar ao pedido</button><button type="button" class="button button-outline button-small" data-fav-del="${f.id}" aria-label="Remover favorito ${esc(f.name)}">Remover</button></div></article>`}).join('')}
document.addEventListener('click',async e=>{const add=e.target.closest('[data-fav-add]'),del=e.target.closest('[data-fav-del]');if(add){const f=favorites.find(x=>String(x.id)===add.dataset.favAdd);const item=f&&buildCartItem(f.sizeId,f.optionIds,1);if(!item)return;cart.push(item);appliedCoupon=null;$('#coupon-message').textContent='';renderCart();customerMessage('#favorites-message',`“${f.name}” foi adicionado ao seu pedido.`);$('#pedido').scrollIntoView({behavior:'smooth',block:'start'});return}if(del){if(!confirm('Remover este favorito?'))return;try{await api('/customers/me/favorites/'+del.dataset.favDel,{method:'DELETE'});favorites=favorites.filter(x=>String(x.id)!==del.dataset.favDel);renderFavorites()}catch(err){customerMessage('#favorites-message',err.message,true)}}});
$('#favorite-open').addEventListener('click',()=>{const m=$('#favorite-builder-message');m.textContent='';if(!selectedSize){m.textContent='Escolha um tamanho primeiro.';return}$('#favorite-save-row').classList.remove('hidden');$('#favorite-open').classList.add('hidden');$('#favorite-name').focus()});
function closeFavoriteRow(){$('#favorite-save-row').classList.add('hidden');$('#favorite-open').classList.remove('hidden');$('#favorite-name').value=''}
$('#favorite-cancel').addEventListener('click',closeFavoriteRow);
$('#favorite-save').addEventListener('click',async()=>{const m=$('#favorite-builder-message'),name=$('#favorite-name').value.trim();m.textContent='';if(name.length<2){m.textContent='Dê um nome ao favorito (mínimo 2 letras).';return}try{const r=await api('/customers/me/favorites',{method:'POST',body:JSON.stringify({name,sizeId:selectedSize.id,optionIds:[...selected]})});favorites.unshift(r.favorite);favoritesLoaded=true;renderFavorites();closeFavoriteRow();m.textContent='Favorito salvo! Você o encontra em Minha conta → Meus favoritos.'}catch(err){m.textContent=err.message}});
$('#favorite-name').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#favorite-save').click()}});

// ===== Esqueci minha senha (a loja redefine pelo WhatsApp) =====
$('#forgot-password-btn').addEventListener('click',()=>$('#forgot-box').classList.toggle('hidden'));
$('#forgot-whatsapp').addEventListener('click',()=>{const phone=String($('#customer-login-form [name=phone]').value||'').trim();const text=`Olá! Esqueci minha senha do site Açaí da Roça e gostaria de redefinir.${phone?`\nMeu celular cadastrado: ${phone}`:''}`;try{whatsapp(text,store?.whatsappNumber)}catch(err){customerMessage('#customer-login-message',err.message,true)}});

// ===== Atualização automática: acompanhamento do pedido e conta =====
var trackTimer=null,trackDirty=false,accountTimer=null;
function showLiveNote(text){const n=$('#live-note');n.textContent=text;n.classList.remove('hidden')}
function startLiveTracking(){stopLiveTracking();if(!trackedOrder||['delivered','cancelled'].includes(trackedOrder.status)){return}trackTimer=setInterval(refreshTracked,20000);showLiveNote('🔄 Este pedido atualiza sozinho — você não precisa consultar de novo.')}
function stopLiveTracking(){if(trackTimer){clearInterval(trackTimer);trackTimer=null}}
function paintStatus(o){const r=$('#tracking-result');const badge=r.querySelector('.tracking-top .status');if(badge){badge.className=`status status-${o.status}`;badge.textContent=statusNames[o.status]||o.status}const spans=r.querySelectorAll('.tracking-progress span');const done=[o.status!=='cancelled',['preparing','out_for_delivery','delivered'].includes(o.status),['out_for_delivery','delivered'].includes(o.status),o.status==='delivered'];spans.forEach((sp,i)=>sp.classList.toggle('done',!!done[i]))}
async function refreshTracked(){if(!trackedOrder||document.hidden||$('#tracking-result').classList.contains('hidden'))return;try{const o=await api(`/orders/track?code=${encodeURIComponent(trackedOrder.orderCode)}&phone=${encodeURIComponent(trackedOrder.lookupPhone)}`);o.lookupPhone=trackedOrder.lookupPhone;if(o.status!==trackedOrder.status){const finished=['delivered','cancelled'].includes(o.status);if(trackDirty){trackedOrder.status=o.status;trackedOrder.canEdit=o.canEdit;paintStatus(o);showLiveNote(`✅ Status atualizado: ${statusNames[o.status]||o.status}. Suas edições em andamento foram mantidas.`)}else{renderTracking(o);showLiveNote(`✅ Status atualizado: ${statusNames[o.status]||o.status}`)}if(finished)stopLiveTracking();loadCustomerOrdersIfSignedIn()}else{showLiveNote(`🔄 Atualizado às ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} — atualiza sozinho.`)}}catch{}}
$('#tracking-result').addEventListener('input',()=>{trackDirty=true});$('#tracking-result').addEventListener('change',()=>{trackDirty=true});
function loadCustomerOrdersIfSignedIn(){if(localStorage.getItem('acaiCustomerToken'))loadCustomerOrders()}
function startAccountLive(){stopAccountLive();accountTimer=setInterval(async()=>{if(document.hidden||!localStorage.getItem('acaiCustomerToken'))return;loadCustomerOrders();try{const d=await api('/customers/me');setPoints(d.loyaltyBalance)}catch{}},30000)}
function stopAccountLive(){if(accountTimer){clearInterval(accountTimer);accountTimer=null}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)return;refreshTracked();loadCustomerOrdersIfSignedIn()});

// ===== Aviso de funcionamento da loja =====
function storeClock(){const tz=store.timezone||'America/Sao_Paulo';const parts=new Intl.DateTimeFormat('en-US',{timeZone:tz,weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const g=t=>parts.find(p=>p.type===t)?.value;let h=Number(g('hour'));if(h===24)h=0;return{dow:{Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6}[g('weekday')],minutes:h*60+Number(g('minute'))}}
function toMinutes(t){const [h,m]=String(t||'0:0').split(':').map(Number);return h*60+(m||0)}
function nextOpeningText(){const days=store.openingDays||[],{dow,minutes}=storeClock(),names=['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];if(days.includes(dow)&&minutes<toMinutes(store.openingTime))return `hoje às ${store.openingTime}`;for(let i=1;i<=7;i++){const d=(dow+i)%7;if(days.includes(d))return i===1?`amanhã às ${store.openingTime}`:`${names[d]} às ${store.openingTime}`}return ''}
function paintStoreBanner(){const el=$('#store-banner');if(!store||!el)return;let text,mode;try{if(store.openNow){mode='open';text=`🟢 Aberto agora — recebemos pedidos até às ${store.closingTime}. Quer para mais tarde? Também dá para agendar.`}else if(store.manualClosed){mode='closed';text='🟣 Pedidos imediatos pausados no momento. Você pode agendar seu pedido para mais tarde.'}else{mode='closed';const next=nextOpeningText();text=`🟣 Estamos fechados agora${next?` — abrimos ${next}`:''} (horário: ${store.openingTime} às ${store.closingTime}). Você pode agendar seu pedido!`}}catch{return}$('#store-banner-text').textContent=text;el.classList.toggle('is-open',mode==='open');el.classList.toggle('is-closed',mode==='closed');el.classList.remove('hidden');$('#store-banner-schedule').classList.remove('hidden');$('#store-status').textContent=store.openNow?'🟢 Aberto para pedidos imediatos · '+store.openingTime+' às '+store.closingTime:'🟣 No momento estamos fechados para pedidos imediatos. Você pode agendar.'}
$('#store-banner-schedule').addEventListener('click',()=>{const t=$('#order-time');t.value='scheduled';t.dispatchEvent(new Event('change'));$('#pedido').scrollIntoView({behavior:'smooth',block:'start'})});
setInterval(async()=>{if(document.hidden||!store)return;try{store=await api('/store');paintStoreBanner()}catch{}},120000);
